import sympy
from sympy import eye, zeros
from sympy.abc import x, y, z

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: I and J are ideals of R generated by elements a and b respectively",
    "¬Q: The intersection I \\cap J is not a principal ideal generated by the least common multiple of a and b"
]

N_HYP = 1
NEG_Q_INDEX = 1

def conditions(witness):
    def get(key):
        if isinstance(witness, dict):
            return witness[key]
        return getattr(witness, key)

    try:
        elements = list(get('elements'))
        add_func = get('add')
        mul_func = get('mul')
        a = get('a')
        b = get('b')
        I = list(get('I'))
        J = list(get('J'))
    except Exception:
        return [False, False]

    def get_generated_ideal(gen):
        generated = {gen}
        queue = [gen]
        while queue:
            curr = queue.pop(0)
            
            # addition closure
            for x_elem in list(generated):
                s1 = add_func(curr, x_elem)
                if s1 not in generated:
                    generated.add(s1)
                    queue.append(s1)
                s2 = add_func(x_elem, curr)
                if s2 not in generated:
                    generated.add(s2)
                    queue.append(s2)
                    
            # multiplication closure
            for r in elements:
                p1 = mul_func(r, curr)
                if p1 not in generated:
                    generated.add(p1)
                    queue.append(p1)
                p2 = mul_func(curr, r)
                if p2 not in generated:
                    generated.add(p2)
                    queue.append(p2)
                    
        return generated

    try:
        I_gen = get_generated_ideal(a)
        J_gen = get_generated_ideal(b)
        H1 = (set(I) == I_gen) and (set(J) == J_gen)
    except Exception:
        H1 = False

    try:
        intersection = set(I).intersection(set(J))
        conclusion_holds = False
        
        # In any ring, an element m is an lcm of a and b if and only if 
        # the ideal generated by m is exactly the intersection of the ideals (a) and (b).
        # Therefore, the intersection is a principal ideal generated by the lcm 
        # if and only if there exists some element m that generates the intersection.
        for m in elements:
            m_gen = get_generated_ideal(m)
            if m_gen == intersection:
                conclusion_holds = True
                break
                
        neg_Q = not conclusion_holds
    except Exception:
        neg_Q = False

    return [H1, neg_Q]